//  Tiny component helpers (React-style structure, vanilla JS)
// ─────────────────────────────────────────────────────────────

function el(tag, attrs = {}, ...children) {
  const element = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (key === 'className') {
      element.className = value;
    } else if (key.startsWith('on') && typeof value === 'function') {
      element.addEventListener(key.slice(2).toLowerCase(), value);
    } else if (key === 'htmlFor') {
      element.setAttribute('for', value);
    } else if (key === 'ariaDescribedBy') {
      element.setAttribute('aria-describedby', value);
    } else if (key === 'ariaInvalid') {
      element.setAttribute('aria-invalid', value);
    } else if (key === 'ariaLive') {
      element.setAttribute('aria-live', value);
    } else if (key === 'ariaAtomic') {
      element.setAttribute('aria-atomic', value);
    } else {
      element.setAttribute(key, value);
    }
  }
  for (const child of children) {
    if (child == null) continue;
    element.append(typeof child === 'string' ? document.createTextNode(child) : child);
  }
  return element;
}

// ─────────────────────────────────────────────────────────────
//  SVG helpers
// ─────────────────────────────────────────────────────────────

function svgIcon(pathData, label) {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 20 20');
  svg.setAttribute('fill', 'currentColor');
  svg.setAttribute('aria-hidden', 'true');
  svg.classList.add('icon');
  if (label) svg.setAttribute('aria-label', label);
  const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
  path.setAttribute('fill-rule', 'evenodd');
  path.setAttribute('clip-rule', 'evenodd');
  path.setAttribute('d', pathData);
  svg.appendChild(path);
  return svg;
}

const ErrorIcon = () =>
  svgIcon(
    'M10 18a8 8 0 100-16 8 8 0 000 16zm-.75-5.25a.75.75 0 001.5 0v-4.5a.75.75 0 00-1.5 0v4.5zm.75-7a1 1 0 100 2 1 1 0 000-2z'
  );

const CheckIcon = () =>
  svgIcon(
    'M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z'
  );

const SuccessCheckIcon = () =>
  svgIcon(
    'M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z'
  );

// ─────────────────────────────────────────────────────────────
//  Validation logic
// ─────────────────────────────────────────────────────────────

const validators = {
  fullName(value) {
    if (!value.trim()) return 'Full name is required.';
    if (value.trim().length < 2) return 'Name must be at least 2 characters.';
    return null;
  },
  email(value) {
    if (!value.trim()) return 'Email address is required.';
    const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRe.test(value.trim())) return 'Please enter a valid email address.';
    return null;
  },
  phone(value) {
    if (!value.trim()) return null; // optional
    // Accept formats: (555) 555-5555, 555-555-5555, +15555555555, etc.
    const phoneRe = /^\+?[\d\s\-().]{7,15}$/;
    if (!phoneRe.test(value.trim())) return 'Please use a valid format, e.g. (555) 555-5555.';
    return null;
  },
};

// ─────────────────────────────────────────────────────────────
//  FormField component
// ─────────────────────────────────────────────────────────────

function FormField({ id, label, type = 'text', required, placeholder, helperText, autocomplete }) {
  const fieldId = id;
  const helperId = `${id}-helper`;
  const errorId = `${id}-error`;

  const labelEl = el(
    'label',
    { htmlFor: fieldId },
    label,
    required
      ? el('span', { className: 'required-mark', 'aria-hidden': 'true' }, ' *')
      : el('span', { className: 'optional-tag' }, '(optional)')
  );

  const input = el('input', {
    id: fieldId,
    name: fieldId,
    type,
    placeholder: placeholder || '',
    required: required ? 'true' : null,
    autocomplete: autocomplete || 'off',
    ariaDescribedBy: helperText ? `${helperId} ${errorId}` : errorId,
    ariaInvalid: 'false',
  });

  const helperEl = helperText
    ? el('p', { id: helperId, className: 'helper-text' }, helperText)
    : null;

  const validationEl = el('p', {
    id: errorId,
    className: 'validation-message',
    ariaLive: 'polite',
    ariaAtomic: 'true',
    role: 'alert',
  });

  const wrapper = el(
    'div',
    { className: 'form-field', 'data-field': id },
    labelEl,
    input,
    ...(helperEl ? [helperEl] : []),
    validationEl
  );

  function validate(showSuccess = false) {
    const error = validators[id]?.(input.value) ?? null;
    // Clear previous state
    validationEl.textContent = '';
    validationEl.className = 'validation-message';
    wrapper.classList.remove('has-error');
    input.setAttribute('aria-invalid', 'false');

    if (error) {
      wrapper.classList.add('has-error');
      input.setAttribute('aria-invalid', 'true');
      validationEl.classList.add('error');
      validationEl.appendChild(ErrorIcon());
      validationEl.appendChild(document.createTextNode(' ' + error));
    } else if (showSuccess && input.value.trim()) {
      validationEl.classList.add('success');
      validationEl.appendChild(CheckIcon());
      validationEl.appendChild(document.createTextNode(' Looks good!'));
    }
    return !error;
  }

  // Validate on blur (after first interaction)
  let touched = false;
  input.addEventListener('blur', () => {
    touched = true;
    validate(true);
  });
  input.addEventListener('input', () => {
    if (touched) validate(true);
  });

  return { wrapper, input, validate };
}

// ─────────────────────────────────────────────────────────────
//  ContactForm component
// ─────────────────────────────────────────────────────────────

function ContactForm({ onSuccess }) {
  const nameField = FormField({
    id: 'fullName',
    label: 'Full Name',
    type: 'text',
    required: true,
    placeholder: 'Jane Smith',
    autocomplete: 'name',
  });

  const emailField = FormField({
    id: 'email',
    label: 'Email Address',
    type: 'email',
    required: true,
    placeholder: 'jane@example.com',
    autocomplete: 'email',
  });

  const phoneField = FormField({
    id: 'phone',
    label: 'Phone Number',
    type: 'tel',
    required: false,
    placeholder: '(555) 555-5555',
    helperText: 'Format: (555) 555-5555 or +1 555 555 5555. Digits, spaces, dashes, and parentheses are accepted.',
    autocomplete: 'tel',
  });

  const submitBtn = el(
    'button',
    { type: 'submit', className: 'submit-btn' },
    'Send Message'
  );

  const form = el(
    'form',
    {
      className: 'contact-form',
      novalidate: 'true',
      onSubmit: handleSubmit,
    },
    nameField.wrapper,
    emailField.wrapper,
    phoneField.wrapper,
    submitBtn
  );

  function handleSubmit(e) {
    e.preventDefault();
    const nameOk = nameField.validate(false);
    const emailOk = emailField.validate(false);
    const phoneOk = phoneField.validate(false);

    if (nameOk && emailOk && phoneOk) {
      onSuccess({
        fullName: nameField.input.value.trim(),
        email: emailField.input.value.trim(),
        phone: phoneField.input.value.trim(),
      });
    } else {
      // Focus first invalid field
      for (const field of [nameField, emailField, phoneField]) {
        if (field.wrapper.classList.contains('has-error')) {
          field.input.focus();
          break;
        }
      }
    }
  }

  return form;
}

// ─────────────────────────────────────────────────────────────
//  SuccessBanner component
// ─────────────────────────────────────────────────────────────

function SuccessBanner({ name, onReset }) {
  const iconWrapper = el('div', { className: 'success-icon' });
  iconWrapper.appendChild(SuccessCheckIcon());

  const resetBtn = el(
    'button',
    { type: 'button', className: 'reset-btn', onClick: onReset },
    'Send another message'
  );

  return el(
    'div',
    { className: 'success-banner', role: 'status', 'aria-live': 'polite' },
    iconWrapper,
    el('h2', {}, `Thanks, ${name}!`),
    el(
      'p',
      {},
      "We've received your message and will get back to you within one business day."
    ),
    resetBtn
  );
}

// ─────────────────────────────────────────────────────────────
//  App — root component
// ─────────────────────────────────────────────────────────────

function App() {
  let submitted = false;
  let submittedData = null;

  const card = el('div', { className: 'card' });

  function renderForm() {
    card.innerHTML = '';
    card.appendChild(
      ContactForm({
        onSuccess(data) {
          submittedData = data;
          submitted = true;
          renderSuccess();
        },
      })
    );
  }

  function renderSuccess() {
    card.innerHTML = '';
    card.appendChild(
      SuccessBanner({
        name: submittedData.fullName.split(' ')[0],
        onReset() {
          submitted = false;
          submittedData = null;
          renderForm();
        },
      })
    );
  }

  renderForm();

  return el(
    'div',
    { className: 'page-wrapper' },
    el(
      'header',
      { className: 'page-header' },
      el('span', { className: 'badge' }, 'Support'),
      el('h1', {}, 'Contact Us'),
      el('p', {}, 'Have a question? Fill in the form and our team will be in touch.')
    ),
    card
  );
}

// ─────────────────────────────────────────────────────────────
//  Mount
// ─────────────────────────────────────────────────────────────

document.getElementById('root').appendChild(App());
